"""Report every cell, including regressions, separately from the pilot."""
import json,statistics
from pathlib import Path
H=Path(__file__).resolve().parent
c=json.loads((H/'comparison.json').read_text());rows=c['rows']
complete=[r for r in rows if r['complete']]
flags=[r for r in complete if r['metrics']['runtime_ns']['delta_percent']>5 and sum(p['runtime_delta_percent']>0 for p in r['pairs'])>=3]
summary=[]
for family in ('sparse','dense','cogentco'):
 rs=[r for r in complete if r['family']==family];ds=[r['metrics']['runtime_ns']['delta_percent'] for r in rs]
 summary.append({'family':family,'complete_cells':len(rs),'faster_cells':sum(v<0 for v in ds),'median_cell_delta_percent':statistics.median(ds) if ds else None,'min_cell_delta_percent':min(ds) if ds else None,'max_cell_delta_percent':max(ds) if ds else None})
(H/'assessment.json').write_text(json.dumps({'failed_processes':len(c['failed']),'complete_cells':len(complete),'families':summary,'flagged_cells':flags,'scope':'Predeclared >5% and >=3/4 slower-pair investigation screen, not statistical significance. No automatic integration.'},indent=2)+'\n')
text=['# HDT promotion-only joins: extended reference comparison','','## Decision','']
if c['failed'] or len(complete)!=38:text.append('Incomplete evidence: retain the candidate experimentally and resolve failed cases before integration.')
elif flags:text.append(f'{len(flags)} cells meet the predeclared regression-investigation screen. Keep the patch isolated; investigate those cells before integration.')
else:text.append('No cell meets the predeclared regression-investigation screen. This is evidence from the optimization matrix, not a proof of universal improvement. Review all cell changes and remaining workload coverage before integration.')
text+=['','The exact [pilot candidate](../2026-10-07-hdt-promotion-joins/README.md) and frozen binaries are reused. Production core remains unchanged. This follow-up is separate from the pilot; samples are not pooled.','','## Coverage and method','','304 planned sequential processes; 38 cells; four paired trials per cell, balanced 2/2 execution order. This covers the full optimization reference matrix used for earlier candidates: sparse 100k/1M, dense512 and Cogentco197. It is **not** the complete 74-cell multi-engine competitor ranking or a new competitor benchmark. See [protocol](protocol.md).','','Percent change is `100*(after median/before median-1)`; negative is better. Family summaries are unweighted medians of cell changes, not aggregate runtime or throughput. Setup is separate. Runtime includes harness checking and timing overhead. Warmed uses an untimed replay on a separate graph; there is no answer cache or hardware-cache flush. RSS is whole-process peak resident memory.','','## Family overview','','| Family | Complete cells | Faster medians | Median cell change | Range |','|---|---:|---:|---:|---:|']
for r in summary:
 if r['complete_cells']:text.append(f"| {r['family']} | {r['complete_cells']} | {r['faster_cells']} | {r['median_cell_delta_percent']:+.2f}% | {r['min_cell_delta_percent']:+.2f}% to {r['max_cell_delta_percent']:+.2f}% |")
text+=['','## Every measured cell','','| Workload | Nodes | Query % | Regime | Before ms | After ms | Runtime change | Faster pairs | Setup change | RSS change | Flag |','|---|---:|---:|---|---:|---:|---:|---:|---:|---:|---|']
for r in rows:
 if not r['complete']:text.append(f"| {r['workload']} | {r['nodes']} | {r['query_percent']} | {r['regime']} | incomplete | — | — | — | — | — | investigate |");continue
 m=r['metrics'];rt=m['runtime_ns'];q=r['query_percent'] if r['query_percent'] is not None else '—'
 text.append(f"| {r['workload']} | {r['nodes']} | {q} | {r['regime']} | {rt['before']['median']/1e6:.3f} | {rt['after']['median']/1e6:.3f} | {rt['delta_percent']:+.2f}% | {r['pairs_faster']}/4 | {m['setup_ns']['delta_percent']:+.2f}% | {m['rss_bytes']['delta_percent']:+.2f}% | {'investigate' if r in flags else '—'} |")
text+=['','## Interpretation and limits','','All observed slowdowns are retained above. The >5% plus at least three slower pairs rule is an engineering screen, not a confidence interval or statistical significance test. Four pairs are limited evidence; do not attribute noisy differences to a particular hardware cause without measurement.','','The pilot structural probes establish less forest work during promotions, and identical counted work on the path1M,q50 control. Timing changes on non-promoting paths must not be advertised as an algorithmic work reduction. This candidate does not change asymptotic HDT bounds or establish superiority over another engine.','','[comparison.json](comparison.json) retains before/after medians, ranges, paired deltas and operation totals/p50/p95/p99. Percentiles are not pooled across runs. The fixed operation count as node count grows also changes the mutated fraction. Cogentco is a real topology with synthetic outages, not a fraud-detection workload.','','## Validation and artifacts','',f"Completed cells: {len(complete)}/38; failed processes: {len(c['failed'])}. Successful runs match reference trace fingerprints and oracle answers; the analyzer checks operation identities and paired HDT counters. [Audit](audit.json) verifies frozen source/binary/artifact hashes and per-cell order. The same candidate already passed full workspace formatting, Clippy, tests/doctests and Rustdoc in the [pilot verification](../2026-10-07-hdt-promotion-joins/reconstruction-verification.json). No new production code was changed for this run.",'','See [assessment.json](assessment.json) for the machine-readable screen and the [preserved patch inventory](../../docs/experiments/2026-10-06-hdt-candidates.md). No commits or staging changes were made.']
(H/'README.md').write_text('\n'.join(text)+'\n')
print(json.dumps(summary,indent=2));print('Flagged cells:',len(flags))
